{
  "name": "opencode-agentmemory-launcher",
  "version": "4.4.1",
  "description": "OpenCode V2 plugin that auto-starts the agentmemory backend with health-check supervision",
  "license": "AGPL-3.0-only",
  "author": "Cle2ment",
  "homepage": "https://github.com/Cle2ment/opencode-agentmemory-launcher#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Cle2ment/opencode-agentmemory-launcher.git"
  },
  "bugs": {
    "url": "https://github.com/Cle2ment/opencode-agentmemory-launcher/issues"
  },
  "keywords": [
    "agentmemory",
    "opencode",
    "plugin",
    "launcher",
    "memory",
    "ai-agent"
  ],
  "type": "module",
  "main": "./dist/agentmemory-launcher.js",
  "types": "./dist/agentmemory-launcher.d.ts",
  "exports": {
    ".": {
      "types": "./dist/agentmemory-launcher.d.ts",
      "import": "./dist/agentmemory-launcher.js",
      "default": "./dist/agentmemory-launcher.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "build": "npm run clean && tsc",
    "clean": "node -e \"fs.rmSync('dist',{recursive:true,force:true})\"",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit",
    "test": "npm run build && node --test test/*.test.mjs"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.5",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
